<?php require_once 'includes/functions.php';$page_title='All Destinations';$q=trim($_GET['q']??'');$cat=(int)($_GET['category']??0);$budget=$_GET['budget']??'';$sql="SELECT p.*,c.name category_name FROM places p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status='published'";$args=[];if($q!==''){$sql.=' AND (p.name LIKE ? OR p.district LIKE ? OR p.description LIKE ?)';array_push($args,"%$q%","%$q%","%$q%");}if($cat){$sql.=' AND p.category_id=?';$args[]=$cat;}if($budget==='low')$sql.=' AND p.estimated_budget<=5000';if($budget==='mid')$sql.=' AND p.estimated_budget BETWEEN 5001 AND 15000';if($budget==='high')$sql.=' AND p.estimated_budget>15000';$sql.=' ORDER BY p.featured DESC,p.name';$st=$pdo->prepare($sql);$st->execute($args);$places=$st->fetchAll();$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();require 'includes/header.php';?>
<section class="page-banner" style="background-image:linear-gradient(90deg,rgba(0,20,22,.8),rgba(0,20,22,.2)),url('https://images.unsplash.com/photo-1500534623283-312aade485b7?w=1600')"><h1>All Destinations</h1><p>Discover amazing places across Bangladesh</p></section><section class="section"><form class="filter-bar" method="get"><input name="q" value="<?=e($q)?>" placeholder="⌕  Search places..."><select name="category"><option value="0">All Categories</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$cat==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select name="budget"><option value="">All Budget</option><option value="low" <?=$budget==='low'?'selected':''?>>Under ৳5,000</option><option value="mid" <?=$budget==='mid'?'selected':''?>>৳5,000–15,000</option><option value="high" <?=$budget==='high'?'selected':''?>>Above ৳15,000</option></select><button class="btn btn-primary">Search</button></form><div class="chips"><a href="destinations.php" class="chip active">All</a><?php foreach($cats as $c):?><a class="chip" href="destinations.php?category=<?=$c['id']?>"><?=e($c['name'])?></a><?php endforeach;?></div><div class="section-heading"><div><h2>Explore places</h2><p><?=count($places)?> destinations found</p></div></div><div class="card-grid"> <?php foreach($places as $p):?><a class="place-card" href="place.php?slug=<?=e($p['slug'])?>"><div class="place-image"><img src="<?=e(image_url($p['cover_image']))?>" alt="<?=e($p['name'])?>"><span class="rating">★ <?=number_format((float)$p['rating'],1)?></span></div><div class="place-info"><h3><?=e($p['name'])?></h3><p>⌖ <?=e($p['district'])?> · <?=e($p['category_name']??'')?></p><small>Estimated budget: <?=money($p['estimated_budget'])?></small></div></a><?php endforeach;?></div><?php if(!$places):?><div class="empty-state">No destinations match your search. Try another filter.</div><?php endif;?></section><?php require 'includes/footer.php';?>
